{"research_date": "2026-09-10", "pairs": [{"pair_id": "conflict_038396d4d059f876e0c3638c", "claim_ids": ["claim_06125bce75957cbf400062f6", "claim_1de9119f093b58a46a3432c5"], "query_ids": ["q_303"], "claims": [{"claim_id": "claim_06125bce75957cbf400062f6", "quote": "Based in Daejon, South Korea, Hanon Systems makes heating and air conditioning systems at a plant in Shorter, Alabama, that opened in 2003 and has expanded at least three times.", "url": "https://apnews.com/article/hyundai-georgia-auto-supplier-hanon-systems-00a71f69f77fb36cf5f41f8e9a263fce", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Hanon Systems"}}, {"claim_id": "claim_1de9119f093b58a46a3432c5", "quote": "A South Korean company will build a $40 million factory in coastal Georgia to make heating and cooling systems near a Hyundai Motor Group auto assembly plant.", "url": "https://apnews.com/article/hyundai-georgia-auto-supplier-hanon-systems-00a71f69f77fb36cf5f41f8e9a263fce", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {}}]}, {"pair_id": "conflict_87c1cf4af57bd46107273ab4", "claim_ids": ["claim_15d65c7e59d8b4ef2e1c6a67", "claim_512e2110ffb8b8e09e4c8354"], "query_ids": ["q_303"], "claims": [{"claim_id": "claim_15d65c7e59d8b4ef2e1c6a67", "quote": "Headquartered in Ulsan, Korea, Duckyang supplies cockpit modules to customers around the world including Hyundai, Kia, Renault Samsung Motors, Genesis, and Mobis.", "url": "https://gov.georgia.gov/press-releases/2021-05-20/gov-kemp-announces-korean-automotive-manufacturer-duckyang-open-companys", "kind": "full_document", "publisher_type": "official_business_regional", "fields": {"company": "Duckyang", "exporting_country": "Korea"}}, {"claim_id": "claim_512e2110ffb8b8e09e4c8354", "quote": "Duckyang, an electric mobility parts supplier of automotive battery modules and energy storage systems to SK Battery America (SKBA), will invest $10 million in opening its first U.S. manufacturing facility in Jackson County.", "url": "https://gov.georgia.gov/press-releases/2021-05-20/gov-kemp-announces-korean-automotive-manufacturer-duckyang-open-companys", "kind": "full_document", "publisher_type": "official_business_regional", "fields": {"company": "Duckyang", "facility": "first U.S. manufacturing facility in Jackson County"}}]}, {"pair_id": "conflict_ad636d4adeab0c46621b8ce7", "claim_ids": ["claim_7d7b12456d558acba8fed8df", "claim_9e63c14d758b027e1e0d0a6a"], "query_ids": ["q_303"], "claims": [{"claim_id": "claim_7d7b12456d558acba8fed8df", "quote": "Duckyang’s new 230,000-square-foot facility will be located at 984 Broadway Avenue in Braselton.", "url": "https://gov.georgia.gov/press-releases/2021-05-20/gov-kemp-announces-korean-automotive-manufacturer-duckyang-open-companys", "kind": "full_document", "publisher_type": "official_business_regional", "fields": {"facility": "230,000-square-foot facility"}}, {"claim_id": "claim_9e63c14d758b027e1e0d0a6a", "quote": "Content produced in North Korea is not presently allowed into the United States, a situation that the KORUS FTA would not change.", "url": "https://www.everycrsreport.com/reports/R41868.html", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"country_of_origin": "North Korea"}}]}, {"pair_id": "conflict_1ea48b94d0a61ef89ad247c2", "claim_ids": ["claim_640ad95161b5d5e31d55a963", "claim_a023f991b2d1e7854412ac35"], "query_ids": ["q_303"], "claims": [{"claim_id": "claim_640ad95161b5d5e31d55a963", "quote": "The KORUS FTA has two specific rule of origin requirements. First, all products must be produced in either the United States or South Korea.", "url": "https://www.everycrsreport.com/reports/R41868.html", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "KORUS FTA"}}, {"claim_id": "claim_a023f991b2d1e7854412ac35", "quote": "Under the proposed KORUS FTA, automakers and most component manufacturers can select one of three options for calculating regional value content.", "url": "https://www.everycrsreport.com/reports/R41868.html", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "proposed KORUS FTA"}}]}, {"pair_id": "conflict_3512dc45512cf438aa3ea4af", "claim_ids": ["claim_8b4a4ebeccf825b420f1108b", "claim_b69c17b8d6cf7401fb22ffdc"], "query_ids": ["q_303"], "claims": [{"claim_id": "claim_8b4a4ebeccf825b420f1108b", "quote": "Like a number of South Korean suppliers, Hanon Systems already supplies a Hyundai assembly plant in Montgomery, Alabama, and a Kia plant in West Point, Georgia.", "url": "https://apnews.com/article/hyundai-georgia-auto-supplier-hanon-systems-00a71f69f77fb36cf5f41f8e9a263fce", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Hanon Systems"}}, {"claim_id": "claim_b69c17b8d6cf7401fb22ffdc", "quote": "Hanon Systems announced Tuesday that it would build the plant in Statesboro, with plans to hire at least 160 new employees.", "url": "https://apnews.com/article/hyundai-georgia-auto-supplier-hanon-systems-00a71f69f77fb36cf5f41f8e9a263fce", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Hanon Systems"}}]}, {"pair_id": "conflict_3725ceac14c2c265168f14de", "claim_ids": ["claim_2c459b3e25009d9ef46099bb", "claim_e1578b8044f522c2f4142bd1"], "query_ids": ["q_304", "q_307"], "claims": [{"claim_id": "claim_2c459b3e25009d9ef46099bb", "quote": "Tariffs on EVs under Section 301 will rise from 25% to 100% in 2024.", "url": "https://mobilitynotes.com/summary-of-ev-related-u-s-tariffs-on-chinese-imports", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 301", "affected_product": "EVs", "duty_rate": "100%", "effective_date": "2024"}}, {"claim_id": "claim_e1578b8044f522c2f4142bd1", "quote": "Tariffs on lithium-ion EV batteries will rise from 7.5% to 25% in 2024", "url": "https://mobilitynotes.com/summary-of-ev-related-u-s-tariffs-on-chinese-imports", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 301", "affected_product": "lithium-ion EV batteries", "duty_rate": "25%", "effective_date": "2024"}}]}, {"pair_id": "conflict_49d16bed2c9eaa77c7d98347", "claim_ids": ["claim_1e7396e2a49cf1ece483646e", "claim_99c23c2e371b083b288808e8"], "query_ids": ["q_305"], "claims": [{"claim_id": "claim_1e7396e2a49cf1ece483646e", "quote": "25% tariffs on certain covered auto parts from any country, effective 12:01 a.m. EDT on May 3, 2025.", "url": "https://www.kelleydrye.com/viewpoints/blogs/trade-and-manufacturing-monitor/tariff-update-list-of-products-covered-by-the-autos-tariffs", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "25%", "effective_date": "May 3, 2025"}}, {"claim_id": "claim_99c23c2e371b083b288808e8", "quote": "subject to 25% tariffs under Section 232 tariffs on imported automobile parts", "url": "https://www.trade.gov/press-release/department-commerce-announces-new-auto-parts-tariff-inclusions-process", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "Section 232 tariffs", "duty_rate": "25%", "effective_date": "October 1, 2025"}}]}, {"pair_id": "conflict_174e9482fdc1666058ff55e3", "claim_ids": ["claim_823011cda73df7db64593f44", "claim_d3b6962d542d6a38abd3bdbb"], "query_ids": ["q_305"], "claims": [{"claim_id": "claim_823011cda73df7db64593f44", "quote": "On April 3, 2025, the Presidential Proclamation Adjusting Imports of Automobiles and Automobile Parts into the United States, and its accompanying Annex I, were published in the Federal Register.", "url": "https://www.kelleydrye.com/viewpoints/blogs/trade-and-manufacturing-monitor/tariff-update-list-of-products-covered-by-the-autos-tariffs", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Presidential Proclamation Adjusting Imports of Automobiles and Automobile Parts into the United States", "legal_authority": "Section 232 of the Trade Expansion Act of 1962", "announcement_date": "April 3, 2025", "effective_date": "April 3, 2025"}}, {"claim_id": "claim_d3b6962d542d6a38abd3bdbb", "quote": "25% tariffs on covered passenger vehicles (sedans, sport utility vehicles, crossover utility vehicles, minivans, and cargo vans) and light trucks from any country, effective 12:01 a.m. EDT on April 3, 2025.", "url": "https://www.kelleydrye.com/viewpoints/blogs/trade-and-manufacturing-monitor/tariff-update-list-of-products-covered-by-the-autos-tariffs", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "25%", "effective_date": "April 3, 2025"}}]}, {"pair_id": "conflict_3a2707b1c42617542ccad7ce", "claim_ids": ["claim_823011cda73df7db64593f44", "claim_9560b95926ffba8ceed6fa4e"], "query_ids": ["q_305"], "claims": [{"claim_id": "claim_823011cda73df7db64593f44", "quote": "On April 3, 2025, the Presidential Proclamation Adjusting Imports of Automobiles and Automobile Parts into the United States, and its accompanying Annex I, were published in the Federal Register.", "url": "https://www.kelleydrye.com/viewpoints/blogs/trade-and-manufacturing-monitor/tariff-update-list-of-products-covered-by-the-autos-tariffs", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Presidential Proclamation Adjusting Imports of Automobiles and Automobile Parts into the United States", "legal_authority": "Section 232 of the Trade Expansion Act of 1962", "announcement_date": "April 3, 2025", "effective_date": "April 3, 2025"}}, {"claim_id": "claim_9560b95926ffba8ceed6fa4e", "quote": "Pursuant to President Donald J. Trump’s proclamation on March 26, 2025", "url": "https://www.trade.gov/press-release/department-commerce-announces-new-auto-parts-tariff-inclusions-process", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"legal_authority": "President Donald J. Trump’s proclamation on March 26, 2025", "announcement_date": "March 26, 2025"}}]}, {"pair_id": "conflict_ac33155f3efb5d74f0a24770", "claim_ids": ["claim_2a69bb341e46bbe21b79479e", "claim_ddef72466cf375331ca358fc"], "query_ids": ["q_306"], "claims": [{"claim_id": "claim_2a69bb341e46bbe21b79479e", "quote": "new trade deals have reduced rates for some — including 15% for the EU and Japan, and 10% for select UK vehicles", "url": "https://blogs.tradlinx.com/auto-tariffs-101-how-u-s-car-import-duties-really-work-in-2025", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "new trade deals", "duty_rate": "15%"}}, {"claim_id": "claim_ddef72466cf375331ca358fc", "quote": "auto imports from the EU, Japan, and South Korea face a 15% total", "url": "https://www.congress.gov/crs-product/IN12545", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "15%"}}]}]}

